// Normalizar payload de error de cualquier workflow
const item = $input.first().json;

const error = {
  // Identificadores
  workflowId: item.workflow?.id || item.workflowId || 'unknown',
  workflowName: item.workflow?.name || item.workflowName || 'unknown',
  executionId: item.execution?.id || item.executionId || $execution?.id || 'unknown',
  timestamp: new Date().toISOString(),

  // Error
  message: item.error?.message || item.message || 'Unknown error',
  description: item.error?.description || item.description || '',
  nodeName: item.error?.node?.name || item.nodeName || item.error?.atNode || '',
  nodeType: item.error?.node?.type || item.nodeType || '',
  stack: item.error?.stack || '',

  // Payload
  trigger: item.trigger || '',
  lastNodeExecuted: item.lastNodeExecuted || '',
  inputData: JSON.stringify(item.inputData || {}).slice(0, 2000),

  // Metadata
  env: (typeof process !== 'undefined' && process.env?.NODE_ENV) || 'unknown',
  source: 'n8n-error-trigger'
};

// Severidad: errores de auth/permiso son CRITICAL
error.severity = 'WARNING';
const criticalPatterns = [/auth/i, /permission/i, /denied/i, /forbidden/i, /401/i, /403/i, /credential/i, /secret/i, /OOM/i, /kill/i, /timeout/i];
for (const p of criticalPatterns) {
  if (p.test(error.message) || p.test(error.description)) {
    error.severity = 'CRITICAL';
    break;
  }
}

return [{ json: error }];

// Dead Letter Queue: persiste errores en staticData
const error = $json;

function getStore() {
  try { return $getWorkflowStaticData('global'); } catch (e) { return {}; }
}
const store = getStore();
store.dlq = store.dlq || [];

store.dlq.push({
  ...error,
  storedAt: new Date().toISOString(),
  acknowledged: false
});

// Mantener solo los ultimos 200 errores
if (store.dlq.length > 200) {
  store.dlq = store.dlq.slice(-200);
}

return [{ json: { ok: true, dlqSize: store.dlq.length, severity: error.severity, workflowName: error.workflowName } }];
